"""query.sql returns the same rows as your reference query, on your data."""
import sqlite3
import sys

def bad_check(msg):
    print("sql: the check is misconfigured: " + msg, file=sys.stderr)
    sys.exit(2)


if len(sys.argv) != 2 or sys.argv[1] not in ("yes", "no"):
    bad_check("ordered must be yes or no")
ORDERED = sys.argv[1] == "yes"


def fail(lines):
    print("sql: FAILED — " + lines[0], file=sys.stderr)
    for line in lines[1:]:
        print("  " + line, file=sys.stderr)
    sys.exit(1)


def norm(v):
    # Floats compared to 9 significant digits; an integral float equals the integer.
    if isinstance(v, float):
        if v == int(v) and abs(v) < 2**53:
            return int(v)
        return float("%.9g" % v)
    return v


def key(row):
    return tuple((v is None, type(v).__name__, v) for v in row)


def run(db, sql, who):
    try:
        cur = db.execute(sql)
    except sqlite3.Error as e:
        return None, "%s: %s" % (who, e)
    if cur.description is None:
        return None, "%s is not a query (it returns no columns)" % who
    return [tuple(norm(v) for v in r) for r in cur.fetchall()], len(cur.description)


def main():
    with open("fixture.sql", encoding="utf-8") as f:
        fixture = f.read()
    with open("reference.sql", encoding="utf-8") as f:
        reference = f.read().strip().rstrip(";")
    with open("query.sql", encoding="utf-8") as f:
        answer = f.read().strip().rstrip(";")
    db = sqlite3.connect(":memory:")
    try:
        db.executescript(fixture)
    except sqlite3.Error as e:
        bad_check("your data (fixture.sql): %s" % e)
    want, wcols = run(db, reference, "your reference query")
    if want is None:
        bad_check(wcols)
    if not want:
        bad_check("your reference query returns no rows on your data, so an empty answer would pass: add rows it returns")
    if not answer:
        fail(["query.sql is empty"])
    got, gcols = run(db, answer, "query.sql")
    if got is None:
        fail([gcols])
    if gcols != wcols:
        fail(["query.sql returns %d column(s); the reference returns %d" % (gcols, wcols)])
    if ORDERED:
        if got != want:
            for i, (g, w) in enumerate(zip(got, want)):
                if g != w:
                    fail(["row %d is %r; expected %r (order matters)" % (i + 1, g, w)])
            fail(["%d row(s); expected %d" % (len(got), len(want))])
    else:
        a, b = sorted(got, key=key), sorted(want, key=key)
        if a != b:
            missing = [r for r in b if r not in a]
            extra = [r for r in a if r not in b]
            lines = ["%d row(s); expected %d, %d missing and %d extra (order ignored)" % (len(got), len(want), len(missing), len(extra))]
            lines += ["missing %r" % (r,) for r in missing[:5]]
            lines += ["extra %r" % (r,) for r in extra[:5]]
            fail(lines)
    print("sql: ok — %d row(s) match the reference%s" % (len(want), " in order" if ORDERED else ""))


main()
